-- The owner approved the four "All" extras on 26 November 2026 and asked
-- for them to be switched on: Where do I feel it?, Sleep check, Unclench
-- and My calm place.
--
-- GENERATED from packages/shared-types/worksheets by emit-sql.ts.
-- Do not hand-edit; regenerate instead.
--
-- The wording is the copy he approved. Unclench and My calm place carry the
-- script timing he set the same day: a second for every three words, never
-- under six; ten seconds of quiet after every line; and on Unclench, five
-- extra seconds on each line that says "hold".
--
-- Approval switches them on: the client Library lists them, a client can
-- open them, and the portal can assign them. Nothing else about them moves
-- — access modes, care-plan labels and the Sleep check's deeper screen are
-- as the drafts migration left them.

INSERT INTO "ToolRegistryEntry" ("id", "tool_id", "label", "label_hi", "text", "chat_guidable", "kind", "summary", "summary_hi", "section", "therapy_modality", "therapist_note", "access_mode", "load_level", "est_minutes", "content_en", "content_hi", "status", "approved_at", "sort_order", "library_group", "care_plans", "sensitive_check", "updated_at") VALUES
    ('c1b2a3d4-0000-4e00-9000-000000000fa1', 'ws_body_map', 'Where do I feel it?', NULL, 'Feelings often show up in your body first. Find where.', false, 'worksheet', 'Feelings often show up in your body first. Find where.', NULL, 'notice_and_name', 'Interoceptive awareness (body scan, somatic mapping)', 'the client taps the parts of the outline where something is present, up to three, then picks feelings for each tapped part. Per part, never a total — two places can carry different feelings and the exercise is about noticing that. There is no strength rating: the approved copy asks only where and what, so the screen asks only that.', 'open', 'light', 5, $ws_ws_body_map${"version":1,"intro":"Before you have words for a feeling, your body often already knows. A tight chest. A knot in your stomach. Shoulders up near your ears. Tap where you notice something.","fields":[{"id":"where","type":"body_outline","prompt":"Where do you feel it right now?","helper":"Tap up to three spots. If you can't find anything, that's okay too.","required":true,"maxSelections":3,"fullMessage":"You can pick up to three. Tap a spot again to remove it.","withFeelings":true,"feelingsPrompt":"What's the feeling there?","feelings":[{"id":"sad","label":"sad"},{"id":"scared","label":"scared"},{"id":"angry","label":"angry"},{"id":"ashamed","label":"ashamed"},{"id":"happy","label":"happy"},{"id":"calm","label":"calm"},{"id":"numb","label":"numb"},{"id":"worried","label":"worried","parent":"scared"},{"id":"panicky","label":"panicky","parent":"scared"},{"id":"unsafe","label":"unsafe","parent":"scared"},{"id":"on_edge","label":"on edge","parent":"scared"}],"regions":[{"id":"head","label":"Head"},{"id":"face","label":"Face"},{"id":"jaw","label":"Jaw"},{"id":"throat","label":"Throat"},{"id":"neck","label":"Neck"},{"id":"shoulders","label":"Shoulders"},{"id":"chest","label":"Chest"},{"id":"heart","label":"Heart"},{"id":"stomach","label":"Stomach"},{"id":"belly","label":"Belly"},{"id":"back","label":"Back"},{"id":"arms","label":"Arms"},{"id":"hands","label":"Hands"},{"id":"hips","label":"Hips"},{"id":"legs","label":"Legs"},{"id":"knees","label":"Knees"},{"id":"feet","label":"Feet"}]}],"closing":{"text":"Now you know where it sits. Next time it turns up, you might notice it sooner."}}$ws_ws_body_map$::jsonb, NULL, 'approved', '2026-11-26'::timestamp, 130, NULL, ARRAY['all']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000fa2', 'ws_sleep_diary', 'Sleep check', NULL, 'Two minutes each morning. See how your sleep and your days connect.', false, 'worksheet', 'Two minutes each morning. See how your sleep and your days connect.', NULL, 'energy_life', 'Sleep hygiene monitoring (self-report diary)', 'bedtime, wake time, restedness, screens before bed and a short note, one entry per night. No medicine field by the owner''s rule — sleep medication is a prescriber decision and is not asked about here.', 'open', 'light', 3, $ws_ws_sleep_diary${"version":1,"intro":"Bad sleep makes everything feel heavier, and when you're tired it's hard to see why. Jot down last night in under two minutes. A rough night is worth writing down too.","fields":[{"id":"night","type":"datetime","prompt":"Which night are you writing about?","helper":"Usually last night.","required":true,"withDate":true,"withTime":false},{"id":"bedtime","type":"datetime","prompt":"When did you get into bed?","withDate":false,"withTime":true},{"id":"wake_time","type":"datetime","prompt":"When did you actually get up?","helper":"Getting up, not waking up. They're often different.","withDate":false,"withTime":true},{"id":"rested","type":"scale_0_10","prompt":"How rested do you feel?","minLabel":"running on empty","maxLabel":"fully charged"},{"id":"screens","type":"choice","prompt":"Were you on your phone or a screen in the hour before bed?","helper":"No judgement. Most of us were.","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}]},{"id":"notes","type":"short_text","prompt":"Anything about last night worth remembering?","helper":"Woke up a lot, mind racing, a late-night call, a noisy house. A few words is enough."}],"closing":{"text":"Done for today. Over a few mornings, you may start to see how your nights and days connect."}}$ws_ws_sleep_diary$::jsonb, NULL, 'approved', '2026-11-26'::timestamp, 140, NULL, ARRAY['all']::TEXT[], true, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000fa3', 'ws_muscle_relaxation', 'Unclench', NULL, 'You''re probably holding more tension than you think. Three minutes to let it go.', false, 'worksheet', 'You''re probably holding more tension than you think. Three minutes to let it go.', NULL, 'calm_my_body', 'Progressive muscle relaxation', 'guided tense-and-release through the main muscle groups. Audio-guided in intent; until the owner approves a voice the script is read on screen and nothing is recorded. Timing set by the owner on 26 November 2026: each line stays long enough to read it — one second for every three words, never less than six — a line that says "hold" gets five seconds for the hold itself, and every line is followed by ten seconds of quiet to notice the release.', 'open', 'light', 3, $ws_ws_muscle_relaxation${"version":1,"intro":"Stress hides in your body: a clenched jaw, tight shoulders, fists you didn't know you were making. You'll gently tighten one part at a time, then let it go. Nothing should hurt. Skip any part that's sore or injured.","fields":[{"id":"settle","type":"instruction","prompt":"Get comfortable, sitting or lying down. Let your hands rest. Breathe out slowly, and let your shoulders drop a little."},{"id":"hands_arms","type":"instruction","prompt":"Hands and arms. Make two loose fists and tighten your arms, just a little. Hold… and let go. Notice how your hands feel now."},{"id":"shoulders_neck","type":"instruction","prompt":"Shoulders. Lift them up towards your ears. Hold them there… and drop them. Feel how far they fall."},{"id":"face","type":"instruction","prompt":"Face. Scrunch it up: eyes, forehead, jaw. Hold… and let go. Let your teeth come slightly apart."},{"id":"stomach","type":"instruction","prompt":"Stomach. Tighten it gently, like you're bracing. Hold… and soften. Let your breath reach your belly."},{"id":"legs_feet","type":"instruction","prompt":"Legs and feet. Point your toes and tighten your legs. Hold… and release. Let them feel heavy."},{"id":"whole_body","type":"instruction","prompt":"Now all of you together, gently. Hold… and let everything go. One long breath out."},{"id":"after","type":"scale_0_10","prompt":"How does your body feel now?","minLabel":"still tight","maxLabel":"loose and easy"}],"script":{"secondsPerWords":3,"minSeconds":6,"gapSeconds":10,"holdExtraSeconds":5},"closing":{"text":"That's it. Check in with your jaw and shoulders again later today."}}$ws_ws_muscle_relaxation$::jsonb, NULL, 'approved', '2026-11-26'::timestamp, 150, NULL, ARRAY['all']::TEXT[], false, CURRENT_TIMESTAMP),
    ('c1b2a3d4-0000-4e00-9000-000000000fa4', 'ws_safe_place', 'My calm place', NULL, 'Build a place in your head you can go to when things get too loud.', false, 'worksheet', 'Build a place in your head you can go to when things get too loud.', NULL, 'calm_my_body', 'Guided imagery (safe place)', 'guided imagery to a place the client builds themselves. The place is asked for first, before any settling step, so the client names it in their own words before the guided part begins. Audio-guided once the owner approves the script and the voice; until then the script is read on screen and nothing is recorded. Timing set by the owner on 27 November 2026: each line stays long enough to read it — one second for every three words, never less than six — and every line is followed by fifteen seconds of quiet to picture the place. The place is the client''s own — nothing is suggested for them.', 'open', 'light', 2, $ws_ws_safe_place${"version":1,"intro":"Think of a place where you feel calmer. It can be real or made up: your nani's kitchen, a quiet beach, your bed on a rainy afternoon. You'll spend a few minutes there. If anything feels uncomfortable, open your eyes and stop. You can come back another time.","fields":[{"id":"choose","type":"short_text","prompt":"Where's your place?","helper":"A few words is enough. If nowhere real feels calm, make one up. That's completely fine.","required":true},{"id":"settle","type":"instruction","prompt":"Get comfortable. Close your eyes if that feels okay, or rest your eyes on one spot on the floor. Breathe out slowly."},{"id":"see","type":"instruction","prompt":"Look around. What do you see? Colours, light, the shape of things."},{"id":"hear","type":"instruction","prompt":"Listen. What can you hear? Rain, waves, quiet, someone humming in the next room."},{"id":"feel","type":"instruction","prompt":"Feel it. The air on your skin, what's under you, warm or cool."},{"id":"stay","type":"instruction","prompt":"Stay a little longer. Nothing is expected of you here. When you're ready, take one slow breath and open your eyes."},{"id":"after","type":"scale_0_10","prompt":"How do you feel now?","minLabel":"very unsettled","maxLabel":"very calm"}],"script":{"secondsPerWords":3,"minSeconds":6,"gapSeconds":15},"closing":{"text":"Your place is yours. You can come back to it any time."}}$ws_ws_safe_place$::jsonb, NULL, 'approved', '2026-11-26'::timestamp, 160, NULL, ARRAY['all']::TEXT[], false, CURRENT_TIMESTAMP)
